full_text = """
sb-ssr-production-auth-token.0=base64-
sb-ssr-production-auth-token.
"""

import base64

part0 = full_text.split("sb-ssr-production-auth-token.0=base64-")[1].split()[0]
part1 = full_text.split("sb-ssr-production-auth-token.1=")[1].split()[0]

b64 = part0 + part1
b64 += "=" * ((4 - len(b64) % 4) % 4)

decoded = base64.b64decode(b64).decode("utf-8", errors="ignore")

# String splitting to find the access token
token = decoded.split('"access_token":"')[1].split('"')[0]

with open("hymn_remaker/.env", "w") as f:
    f.write(f"UDIO_OAUTH_TOKEN={token}\nREMAKE_PRIORITY=udio\n")
print(f"Token extracted: {token[:20]}...")
